export const guides: Guide[] = [
  {
    slug: 'your-first-match', title: 'Your first match', description: 'Choose your players, set the rules, and get onto the live court.', category: 'Getting started', duration: '4 min', screen: 'new-match', screenAlt: 'Rallymetrica match setup showing tracking options',
    intro: 'A little setup gives every point its context. Choose the two players, the match format, and how much detail you want to record.',
    steps: [
      { title: 'Start with the players', body: 'On **Sessions → Matches**, tap **+ New match**. In **Players**, tap **Choose** in each slot. Select two different players from your roster, or tap **+ New player** and save a new player.' },
      { title: 'Set the zones the stats read', body: 'Open a player, then **Zones**. One court, three groups. **Court:** **Channel**, the band down the centre a middle ball lands in (default half the width — outside it a ball is crosscourt or down the line); **Deep**, the band at the far baseline your balls should reach (default the last 20%, never past the service line); **Mid**, the band on your own side you build from, with **Finish** — the box you close from — set automatically as what is left to the net. **Serve:** how wide the T and wide strips are. **Stroke:** how far your forehand zone reaches across the court, in %, length or O\'Shannessy\'s lanes A–D. The value sits in the slider\'s thumb; tapes under the court show each line as a distance. Every stat that mentions a zone — Deep, Channel, Finish: Punished, Into their FH zone — reads these lines, and a match keeps the lines it was played with.', screen: 'profile-zones', alt: 'Rallymetrica player profile Zones tab with Court, Serve and Stroke settings' },
      { title: 'Set the opening serve and ends', body: 'Choose who **Serves first**. Then look at the court: the player at your end — the end you are sitting behind — should be at the bottom. If not, tap **Swap ends**. Set it once; from here the court changes ends with the players at every changeover.' },
      { title: 'Choose the rules', body: 'Open **Rules** and select the format you are playing, such as **Best of 3 · TB**, **Best of 3 · full**, or **Fast4**. The lit format’s **›** opens **Customize**: sets, games per set, the **set tiebreak** played at games-all (5, 7 or 10 points), the **final set** — a full set, a **match tiebreak** in its place (7 or 10 points), or advantage with no tiebreak — and the deuce rule. The sentence under the rows reads the whole format back. Check it before the first point — a match’s rules cannot change once it has started.' },
      { title: 'Check the zones', body: '**Zones** draws both players’ zones on one court — each player’s channel, deep, mid and finish zones, forehand zone and serve strips, as saved on their profiles — each half its owner’s Mid · Finish and the other player’s Deep — with the sliders for the lit player under it; switch players on the track. A drag here changes this match only and the court redraws as you go; **Reset** returns the player to their profile’s values. Read the sliders in %, feet or metres, or the forehand in lanes, as set under **Settings → Zones** — see *Set the zones*.' },
      { title: 'Choose your tracking level', body: 'In **Tracking**, choose **Score**, **Counter**, or **Detailed**. Score keeps the point winners; Counter adds shots and endings; Detailed records landings on the court.' },
      { title: 'Start the match', body: 'Optionally set **Surface**, **Court**, and **Use location and weather**. Both players are required, but weather is optional. Tap **Start match** to open the live court.' },
    ],
    notes: ['Setup opens with your saved default rules and tracking level.', 'A change on the Zones tab applies to this match only; the profile keeps its own values.', 'You can start without waiting for weather.', 'A rally or serve session is set up in the same frame from the Rally and Serve pages — see the three session guides.'],
  },
  {
    slug: 'tracking-modes', title: 'Choose your tracking mode', description: 'Score, Counter or Detailed: what each level asks of you on court, and what each one buys you in the report.', category: 'Getting started', duration: '7 min', screen: 'live-counter', screenAlt: 'The live court in Counter mode: one tap per shot, then the ending',
    intro: 'The tracking level is the one decision that shapes everything after the match. It sets how many taps a point costs you in the stands and, in return, which pages and rows the report can fill. Pick it for the match in front of you, not for the report you would like to have.',
    steps: [
      { title: 'Open the tracking options', body: 'Go to **Sessions → Matches → + New match → Tracking**. The track reads **Detailed · Counter · Score**; the level in force is lit, and one grey line under it names what that level records. Your default level is set under **Settings → Default tracking**, so a regular scorer sets it once.' },
      { title: 'Score: one tap a point', body: 'You tap the side that won the point. Nothing else. From that one fact the engine keeps the score under the match’s rules, so it knows every **break point**, **set point** and **match point** before it is played, and it draws the **Momentum** curve. The report gives you **Cover**, **Momentum (Points)**, **Points** (points won · break points won), the whole **Pressure** page — all twelve rows are read from the score — and the **Timeline**. What it cannot tell you: how points ended, anything about the serve, where the ball went. Use it when you are scoring one-handed from the stands with a crowd around you, when you are new to the app, or when the result and its pressure moments are the question.' },
      { title: 'Counter: one tap a shot, then the ending', body: 'You tap once for every shot in the rally — no placement, only the count — then say how the point ended: **Ace · Service winner · Winner · Forced error · Unforced error · Double fault**, and the wing. That unlocks everything about serving and returning and about errors: **Serve** (1st and 2nd serve in and points won, aces, double faults), **Return**, winners and the error split on **Points**, **Aggression** (the margin and efficiency, built from winners, forced and unforced errors), and rally length as a cut (0–4 · 5–8 · 9+). A Counter match answers *who built the points and who gave them away* — the practice-plan question. What it cannot tell you: where anything landed, so no **Placement**, no pattern results, and in **Aggression** every forced error reads as the attacker’s credit and nothing is punished. Use it when you can watch every ball but cannot look down to place each one.' },
      { title: 'Detailed: tap where the ball lands', body: 'You tap the court where each ball lands — the serve, the return, every rally ball — and the ending follows from the last tap: a ball outside the lines or on the net asks forced or unforced, a ball in play that was not reached is a winner. That adds the geometry: **Placement** (the zones as rows — depth, width, the forehand zone, the lanes, the serve strips — under Balls · Punished · Rewarded · Converted, with the landings on the court behind a switch), the **Punished** column and the intent margin in **Aggression**, the full rally path in **Replay**, and **Patterns** — a pattern can only be matched against landings. Use it when the tactical question is *where*: a second serve that goes in but goes nowhere, a backhand that never goes down the line, a pattern the coach assigned.' },
      { title: 'What the tracking level costs you', body: 'A Score point is one tap. A Counter point is the rally length plus two (the ending and the wing) — a nine-ball rally is eleven taps. A Detailed point is the same number of taps, but each one is placed, so your eyes leave the court for each. The honest rule: you can track one level deeper than you can comfortably watch. If you find yourself tapping after the point to catch up, drop a level — the footer control does it mid-match.' },
      { title: 'Change it during the match', body: 'The middle footer control cycles **Detailed → Counter only → Score only** and back. A change keeps every point already recorded exactly as it was and applies from the next point; shots already tapped in the open point are kept, an unconfirmed placement is cleared. The report reads each point at the level it was recorded, so a match that went Detailed for the first set and Score for the second has Placement rows with the first set’s balls alone — and the rows say so by their counts.' },
      { title: 'What each level looks like in the report', body: 'Open a Score match and the page picker shows **Cover · Momentum · Points · Pressure · Timeline**; the Serve row on Points is absent, not dashed. Open a Counter match and **Aggression · Serve · Return** appear, plus rally length on every table page’s track. Open a Detailed match and **Placement · Patterns** appear, and Replay draws the ball paths instead of the point markers. The reference lists every row with the level it needs: Learn → The stats engine → What each tracking level unlocks.' },
    ],
    notes: ['Free includes two Counter or Detailed matches to try; after those, Counter and Detailed require the Player plan or above. Score stays free, unlimited.', 'The Stats tab charts every match that captured the metric: a Score match is a gap on 1st serve in, never a zero — so a season tracked at mixed levels still trends honestly.', 'Pattern focus is offered only in Detailed setup; switching away from Detailed mid-match stops pattern matching from that point.', 'Practice sessions are always Detailed — a session exists to be tracked — so their footer item is a label (VS · CO-OP, or PAIRS · 1ST · 2ND), not a switch.', 'A linked coach receives the match at whatever level you record; the coach cannot add detail from the stands on their phone.'],
  },
  {
    slug: 'live-tracking', title: 'Track, correct, and resume', description: 'Read the court from your seat, record the point, undo a mistake, and pick up where you left off.', category: 'On court', duration: '7 min', screen: 'live', screenAlt: 'Rallymetrica live court and Undo control',
    intro: 'The court is drawn from where you sit and turns with the players at every changeover, so a tap lands where you saw the ball land. Then follow the live court’s prompt one action at a time; the scoring updates as you record points, and you can correct a mistake or leave the match open.',
    steps: [
      { title: 'Read the court from your seat', screen: 'live-half-return', alt: 'Half-court view after a serve, with a prompt for the return landing', body: 'The court is drawn from where you are sitting, not from where the hitter stands. In **Full court** both halves are shown: the player at your end is at the bottom, the far player at the top, each name beside its half, and a soft glow on the half the ball is heading for. In **Half court** only the half the ball is about to land in is shown, larger — the same picture with the other half cut away, so your end is drawn with the net at the top and the far end with the net at the bottom. Left is always your left. Switch between them any time from the match menu: **☰ → Court view**.' },
      { title: 'Let the court change ends with the players', screen: 'live-turned', alt: 'The full court after a changeover: the names\' columns swapped, the player at your end at the bottom', body: 'At every changeover — after the first game of a set, then every two games, and every six points in a tiebreak — the players swap ends and the court turns with them, so the player now at your end is at the bottom again. Nothing to tap; the names and the glow tell you whose half is whose. Sitting behind a baseline, hold the phone upright. Sitting beside the net post, turn the phone sideways so the net runs across the screen the way it runs across your view — the two halves are then left and right, and the changeover swaps them. A faint dotted arrow joins the last two balls so you can see at a glance which way the ball just went.' },
      { title: 'Follow the court prompt', body: 'In **Detailed**, tap the serve landing, then each return or rally landing. In **Counter only**, tap once for the serve and each shot. In **Score only**, tap the point winner’s side.' },
      { title: 'Record how the point ended', body: 'In Counter or Detailed, choose the appropriate ending, such as **Ace**, **Service winner**, **Winner**, **Unforced error**, or **Forced error**. In Detailed, an error requires an outside landing or a net tap.' },
      { title: 'Confirm the point', body: 'Review the ending sheet, choose **Forehand**, **Backhand**, or **Other** when prompted, then tap **Save point**. **Star** and **Add note** are optional. Score only awards the point directly.' },
      { title: 'Correct or take a break', body: 'Use **Undo** to reverse a draft, unconfirmed placement, or earlier recorded action. Use the left footer control to return to the app. Your match remains live; tap **Resume** on its card to continue.' },
      { title: 'Finish the match', body: 'Open the match menu and select **End match**. If the score has not decided the result, select the winner and confirm **End match**.' },
    ],
    notes: ['Fault, Double fault, and Let appear during serving as appropriate.', 'The phone answers your taps without you looking: one light tick for a landing that registered, two quick ticks for an ending that costs the point, a heavier tick for Undo, and a warning buzz for a tap the court refused. **Settings → Haptics** turns them off; an iPad has none.', 'Leaving keeps the current score, open point, and time on court available to resume.', 'Undo also works after you resume a match.', 'A finished match or session opens its report from its card; the court is reached only from a live card’s Resume.'],
  },
  {
    slug: 'zones', title: 'Set the zones. Read them your way.', description: 'The channel, the deep zone, the forehand zone and the serve strips are each player’s own lines — set in %, feet or metres, the forehand in O’Shannessy’s lanes.', category: 'Getting started', duration: '6 min', screen: 'profile-zones', screenAlt: 'A player’s Zones tab: the court with the zones drawn, the sliders under it',
    intro: 'Every placement number in a report — deep landings, middle balls, forehands from the forehand side, serves to the T — is read against lines the engine draws on the court. Those lines are not the court’s; they are the player’s. A junior’s deep ball is not an adult’s, a left-hander’s forehand side is the other side, and a coach who thinks in feet should not have to think in percentages. Set them once per player, and read them in the units you use on court.',
    steps: [
      { title: 'Four zones, and what each one feeds', body: '**Channel** is the band down the centre of the court, baseline to baseline, measured across its width: a ball inside it is a middle ball, outside it crosscourt or down the line — the angles that move an opponent. Half the width by default. **Deep** is the band at the far baseline a player’s balls should reach — the last 20% by default, never past the service line. **Mid** is the band on the player’s own side he builds from, and **Finish** — set automatically as what is left to the net, the service box by default — is where he closes a point from. Coaches call these the deep, the mid-court and the attack zones; the three together are Giampaolo’s thirds, with two sliders instead of a law. **FH zone** is how much of the court, from the forehand sideline, the player should take with a forehand. **T · wide** is the width of the two strips at the edges of each service box a serve has to find to count as a target serve. Every Placement row, the landing court, the serve court’s targets and pattern matching read through these lines, and a match keeps the lines it was played with.' },
      { title: 'Where to set them', body: 'On a player’s profile, **Zones**: the court draws the zones as you move the sliders, and **Reset** returns them to the app’s defaults. Under the court the sliders are grouped as the zones are — **Court** (Channel · Deep · Mid, with Finish read beneath), **Serve** (T · wide), **Stroke** (FH zone); the value sits in the slider’s thumb and the tapes under the court show each line as a distance from the baseline. A match starts from each player’s saved values: **New match → Zones** shows both players on one court — each half its owner’s Mid and Finish and the other player’s Deep — and a drag there changes that match only.' },
      { title: 'Read them in %, feet or metres', body: '**Settings → Zones → Court zones** picks the scale: **%** of the court’s width (the channel and the forehand zone), of the half court (deep) or of the service box (T · wide), in steps of 5 — or **Length**, in feet or metres depending on **Settings → Units**, in tenths. The value sits in the slider’s thumb; a changed one turns yellow. The zone itself does not move when you change the scale — only how you read it: a channel of 25% is 6.8 feet or 2.1 metres of a 27-foot singles court, and a deep zone of “the last 20%” is the last 7.8 feet of the half.' },
      { title: 'O’Shannessy’s lanes', body: 'Craig O’Shannessy divides the court’s width into four equal lanes, **A B C D**, and the letters belong to the court, not the player: **A** is always the wide lane on the deuce side, **D** the wide lane on the ad side, whichever hand you hold the racket in. For a right-hander the forehand lives in A, and his rule of thumb is that the forehand should own **A, B and C** and the backhand only **D** — three lanes to one. A left-hander’s forehand lives in D, so the same rule reads **D, C and B** for the forehand and **A** for the backhand. **Settings → Zones → FH zone → Lanes** makes the forehand slider count lanes, one to four, from the player’s forehand side — A · B · C for a right-hander, D · C · B for a left-hander. Under Lanes the court letters the four lanes on the player’s half and shades the forehand zone lane by lane, light at the forehand sideline and darker toward the far edge, so the handover to the backhand is the strongest line on the court.' },
      { title: 'Read the court', body: 'The fills are gradients and they say what the zone means. Deep is blue and strongest at the far baseline, where the deepest ball lands; Mid is gold from the player’s own deep line toward the net; Finish is cyan, fading to the net. The forehand zone darkens away from the forehand sideline — the boundary where the backhand takes over is the strongest edge. The channel is purple, strongest on the centre line. The serve strips are cross-hatched in the accent, broken at the T and at the net so the two boxes never read as one. The same drawing appears on the profile, in match setup and under the report’s Placement court.' },
      { title: 'A match of its own', body: 'In **New match → Zones** the player track names the two players; the lit one’s sliders show. The values start as the player’s profile; a changed value turns yellow and **Reset** brings that player back to their profile. The match keeps a copy of what it was played under, so a later change to the profile never rewrites an old report.' },
    ],
    notes: ['The defaults: channel 50%, deep the last 20%, the mid line on the service line (so Finish is the box), forehand zone 75% (A · B · C), T · wide 20% of the box.', 'Ranges: channel 10–75%, deep the last 10–45% (never past the service line), the Mid band 1 m up to where Finish would drop under half the box, forehand zone 25–100% — one lane to the whole court — and T · wide 5–25%.', 'The scale is how the sliders read, not how the zones are stored: reports, the stats CSV and backups keep the shares, and a phone set to metres reads another phone’s backup exactly.', 'Serve sessions draw the server’s T and wide strips from the same traits; a serve the server calls wide and the map calls middle is a conversation about the strip width, not the serve.'],
  },
  {
    slug: 'rally-sessions', title: 'Rally sessions: a game with a score', description: 'First to 11, 15 or 21 in blocks, a serve or a feed to start, one rally one point — and the match report on a practice game.', category: 'On court', duration: '8 min', screen: 'rally-court', screenAlt: 'The live court on a VS rally session: blocks on the board and the tally',
    intro: 'A VS rally session is the competitive drill: points played for a score without a match’s length or its scoring ladder. The court, the taps and the report are the match’s; what changes is the format — a tally in blocks, a rotation that says who starts, and a choice of serve or feed. Sessions are on the Player plan and up; on Free they are shown locked.',
    steps: [
      { title: 'Open the Rally page', body: 'The **Sessions** tab has three pages — **Matches**, **Rally** and **Serve** — each with its live rail, its finished list and its filters. On **Rally** the filters are the player, **Any partner**, the mode track **All · VS · Co-op** and the window; the header action reads **+ New rally**. A finished session’s card opens its report; only a live card’s **Resume** goes to the court.' },
      { title: 'Set the format', body: 'Choose the two players, then the **Format** presets: **First to 11 · 15 · 21**, **Timed 10** or **Open**, with the lit preset’s details beneath. **Blocks** (one to five): each block is a race to the target, and the session goes to the player who takes the majority — three blocks to 11 is a practice set. **Start** (**Serve** or **Feed**). **Serves** (**2** or **1**) appears on a serve start: one serve is the second-serves-only drill, a fault loses the point. **Rotation** (**Alternate · Every 2 · Every 3 · Winner · Loser**) says who starts the next rally, and the record keeps every rally’s starter without a tap. These are rules: fixed once the session starts, like a match’s. Tracking is always Detailed.' },
      { title: 'Choose serve or feed deliberately', body: 'A **serve start** plays the serve as a match does — two serves or one, lets replayed, the side alternating with the count — and the report keeps its **Serve** and **Return** pages, the serve zones and the serving · returning cut. Use it to put the serve under pressure, or to drill a serve-started pattern. A **feed start** tracks nothing until the receiver’s first ball; a bad feed is re-fed, no point. The report then has no serve facts at all — no Serve or Return page, no serving · returning track, no Serve · Return balls on the landing maps. Use it when the drill is the rally and the serve would only add noise.' },
      { title: 'Play it like a match', body: 'The live court is the match court — Full or Half court from the menu, drawn from your seat, turning with the players at a changeover. One rally is one point: tap the landings, the ending, **Save rally**; **Undo** as usual. The board shows finished blocks as **B1 · B2** columns and the open block’s tally under **Score**; the dot marks who starts the next rally. A block speaks when it is won — **Block 1 to Asiya · 11–8** — and the session ends on its blocks, its clock, or **End session** from the menu. A session that ends level — the clock running out at 9–9, or an open game ended from the menu — is a tie: no winner, no crown. A linked coach receives it live, with a notification at its start and end.' },
      { title: 'Read the cover and Momentum', body: 'The cover reads the tally per block, then **Mode · Format · Start · Length** — the standard the numbers are judged against. **Momentum** is a race, not a tennis score: the curve is the chance of reaching the target first from the current tally, with the rally-win rate learned from the session itself. So 3–0 in a race to 11 barely moves it and 9–9 is where every rally is worth a tenth of the block; a timed session reads the chance of leading when time runs out. The starred swing marks the run that turned the block; tap it to compare the stretches either side — points played, win chance, winners, errors. Switch **Points → Aggression** under the legend for form: who had been building more than giving away over the last dozen rallies.' },
      { title: 'Read the tables', body: 'The report is the match report with blocks for sets: **Aggression**, **Points**, **Placement**, **Patterns**, **Timeline**, and **Serve · Return** on a serve start. What a tally cannot hold is absent: no **Pressure** page, no break-point row, no **Situation** or **Score** cut — the block track **B1 · B2** stands alone at the top, and each page keeps its own tracks (serving · returning, rally length, starred rallies). Read them as on a match — the reports guide — with one difference worth using: a rally session is the place to test one thing, so put the cut on before you read. **Points** under **9+** says whether the long-rally drill is being won; **Serve** on a **Serves · 1** session is the second serve under real pressure, with the double-fault row reading **Faults** and no Return page.' },
      { title: 'Read it across sessions', body: 'Sessions are not charted on the Stats tab; a session’s trend is its own report’s. Compare two sessions by opening both covers: the same format, the same start, the tally per block. Assigned patterns count on a rally session as on a match, and a session is the cleaner test — fewer rallies, one opponent, the drill you chose.' },
    ],
    notes: ['On a one-serve session a fault loses the point and is recorded as a double fault; the Serve page keeps 1st serve in · pts won · Aces · Service winners · Faults · the zones, and the Return page is absent.', 'A VS rally takes a focus pattern in setup like a Detailed match; the Patterns page reads attempts · completions · won.', 'Rotation is a rule, not a control: the court carries no serve · feed switch, the dot already says who starts.', 'The session over on its blocks or clock speaks; stopping early is End session from the menu, and the record keeps its tally.', 'The same report component draws a rally session and a match; the kind decides the pages, never a second screen.'],
  },
  {
    slug: 'coop-sessions', title: 'Co-op sessions: count the run', description: 'Two players keep the ball in play; any miss ends the run. Read the runs, the two lines, the endings and the pace.', category: 'On court', duration: '8 min', screen: 'coop-court', screenAlt: 'The live court on a co-op session: the run in progress and the best run',
    intro: 'A co-op session has no winner. Two players rally together and the count is the score: how long the ball stayed in play, how many times, who ended it and how. It is the consistency drill written down — and its report is the one place where the average and the median of a thing are read side by side.',
    steps: [
      { title: 'Set it up', screen: 'coop-between-runs', alt: 'Between runs on a co-op court: the feeder pill in the ending band — tap it to switch who feeds', body: 'On **Sessions → Rally → + New rally**, choose **Co-op** as the mode and the two players — the second is a **Partner**, not an opponent. The formats are **Timed 5 · 10 · 15** or **Open**; a co-op has no blocks and no target. Every run starts with a **feed** (the **Start** row is fixed on Feed): the count wants a ball kept in play, not a serve hit into a box. Tracking is always Detailed.' },
      { title: 'Play it', body: 'The board is one shared row — **Runs · Best** and the run in progress, the pair’s names above it. Who feeds is a pill in the divider between runs — **Asiya feeds ⇄** — and a tap flips it: the one mid-session change allowed, because it changes no statistic. The feed is not counted; the receiver’s first ball is the first tap. Tap every landing as on the live court. Any miss ends the run — a ball outside the lines or on the net, or a ball in play that the partner could not reach (unplayable) — and the run is saved with its balls, its seconds, who ended it and how. **Undo** reverses the last tap. The session ends on its clock or **End session**.' },
      { title: 'Read the RUNS page', body: 'Every run is a bar, in order, the longest lit in yellow and the shortest in coral. Two dashed lines cross the bars: the **average** and the **median** run. Read them together. The median is the run you can expect — half the runs were longer, half shorter — and it does not move when one run reaches forty. The average does: it is pulled up by the few long runs. So **average well above median** means a session of short runs with a handful of long ones — the pair can rally, but not on demand; the closer the two lines, the steadier the pair. *Average 14 · median 9* and *average 10 · median 9* are two different pairs with the same median.' },
      { title: 'Read the cells', body: 'Beneath the bars the session in numbers: **Runs · Longest · Shortest · Average · Median · Over 10 · Balls · Balls a minute**. **Over 10** counts the runs that passed ten balls — the consistency target coaches actually set (“five over ten today”), and the number to compare week to week. **Balls a minute** is pace over the lit runs’ own seconds, not the clock, so the walking between runs never dilutes it: 28 a minute is a pair hitting flat out, 18 is a controlled, deep exchange. A cut recomputes the bars, both lines and every cell from the lit runs alone, so a length cut or a starred run narrows the pace with the count.' },
      { title: 'Read ENDINGS', body: 'A run has no winner, only an ender. **ENDINGS** takes the Points page’s place and says who ended the runs and how: **Runs ended** (with each player’s share), **Into the net**, **Long**, **Wide**, **Unplayable** (in, but the partner could not play it) and **Balls hit**. Each ending points somewhere: net misses to height and margin over the net; long to over-hitting or late contact; wide to direction; unplayable to a ball the partner should learn to reach — or to a player who is not keeping the task and is hitting winners in a co-op. A pair whose misses are nearly all long is a pair swinging too hard for the drill; nearly all net is a pair playing too safe.' },
      { title: 'Read the per-player rows', body: 'Under the RUNS chart each player has **Balls hit**, **Balls a minute**, **Runs ended**, and the **Average · Median · Longest run** they ended. **Runs ended** says who the weaker link is; the three run figures say in which kind of run. A player who ends the short runs misses early — the first balls after the feed; one who ends the long runs loses concentration late. **Balls hit** should be near equal in a co-op; a gap means one player is taking two balls to the other’s one, which the Timeline will show.' },
      { title: 'Read the rest', body: '**Placement** reads the rally balls and the ending balls (**Rally · End**, one at a time), as a table or on the court: a deep share under 40% is the depth the misses were made of; the End court shows where the misses went. **Patterns** reads completions of attempts with no won — there are no points to win — which makes a co-op the cleanest place to drill a sequence. **Timeline** lists every run — **Run 7 · 23 balls · ended · net** — with its seconds. There is no Momentum, Aggression, Serve, Return or Pressure: a co-op has no points and no serve.' },
    ],
    notes: ['Sessions are not charted on the Stats tab; the RUNS page is a co-op’s trend, and Over 10 is the number to compare across sessions.', 'The feed is never counted and a bad feed is re-fed: a run is the balls kept in play after it.', 'A linked coach receives a co-op live like a match, with a notification at its start and end.', 'The same report component draws a co-op, a VS rally and a match; the kind decides the pages.'],
  },
  {
    slug: 'serve-sessions', title: 'Serve sessions: a basket at a target', description: 'Blocks of serves judged against the target you call — in %, on target %, the streak, and the session over time.', category: 'On court', duration: '9 min', screen: 'serve-court', screenAlt: 'The serve court: the side and target strips, the running in and on-target shares',
    intro: 'A serve session is one server and a basket of balls, served in blocks against a target called on the court. Two numbers judge every block — was the serve good, and did it go where it was aimed — and the report draws the session over time so that a good start that fell apart does not hide behind a percentage.',
    steps: [
      { title: 'Set it up', body: 'On **Sessions → Serve → + New serve**, choose the **Server** and the **Format**: **Pairs** (a second serve follows a fault, so a block counts points), **1st only** or **2nd only** (a block counts serves). **Blocks** (one to five) and **Block size** (5 · 10 · 20). No side and no target here — both are called on the court, per block. Tracking is always Detailed.' },
      { title: 'Call the side and the target', body: 'The court is the live court’s half with the service boxes lit, drawn from where you stand: by default from **behind the server** — the net at the bottom, the deuce box on the left, the boxes read as the server sees them. Standing on the other side, behind the receiver, switch it from the menu: **☰ → Standing behind → Receiver** turns the court round — the net at the top, the deuce box on the right — so left is still your left. Every serve is stored in the server’s frame whichever way you look, so the report and the trait read the same from either end. Under the court two strips: **Deuce · Ad** for the side, and **T · Mid · Wide** for the block’s target. A block always has one target — it is the aim the next serve is judged against, not a filter. The **T** and **Wide** zones are the server’s serve-target trait from their profile’s **Zones** — a share of the service box, a fifth by default — both drawn with a hatch, the block’s target lit; the middle is the plain box between them. Change the side or the target between blocks; within a block it stands.' },
      { title: 'Serve, tap, type', body: 'One serve is one tap where it landed: inside the box is in, and the band it fell in — T, middle or wide, the T and wide bands the server’s own width — is its zone; outside the box, or on the net line, is a fault. On **Pairs** a fault brings the second serve — **2nd serve** lights until it is hit, and a missed second serve is a double fault. Optionally tap the type after the landing: **Flat · Slice · Kick**; a fault carries the type it was meant to be. **Undo** removes the last serve. The running cells read **In %** and **On target %**; the block closes by itself on its count and shows its summary — **Block 1 · Deuce · Wide target**, so many of ten in, on target, the longest streak, 1st and 2nd, T · Mid · Wide — with **Next block** or, after the last block, **End session** alone. If the app is closed between a block’s first picks and its first serve, the picks are kept.' },
      { title: 'Read the cover', body: 'The blocks as cells across the top — **In** over the block’s unit (points in Pairs, serves otherwise), the best block lit — then **In %** and **On target %** for the session, and **Format · blocks**. The two numbers are different questions. **In %** is whether the serve was good. **On target %** is read *of the serves in*: 60% in and 50% on target means half the good serves found the zone you called. A high in % with a low on-target % is a serve that goes in but will not go where it is sent; the reverse is a serve that knows where it is going and misses too often.' },
      { title: 'Read the SERVE page', body: 'The table lists the catalogue: on Pairs **Points with a serve in** first (the share of points that ended with a good serve — what a match would count), then **Serves in**, **1st** and **2nd serve in**, **Double faults** (Pairs and 2nd only), the **Longest streak**; then the target rows — **On target** and the shares **To the T · To the middle · Out wide** — and the types **Flat · Slice · Kick**. The cut track is the session’s own: **block**, **1st · 2nd** (Pairs only), **Deuce · Ad** (when both sides were served) and the **type** (when any serve was typed). Under a cut the target rows show the cut against the whole session, lit when the cut beat the day: **Deuce** against the session says which side the serve is weaker from; **Kick** against the session says whether the kick serve is the one that finds the zone. A row the cut would empty or merely restate is greyed — the first-serve rows under 2nd, the type shares under a type.' },
      { title: 'Read TREND', body: '**TREND** draws the session on one axis after every serve: the running **in share**, the running **on-target share** and the **streak** so far (consecutive serves in, reset by a fault). The switch beneath the chart picks the reading. On **STREAKS**, the streak is the measure of repeatability the percentage hides — 70% in with a longest streak of 3 is a serve that goes in but not twice running; 60% in with a streak of 9 is a serve that was grooved for a stretch and lost. The mean and the median streak sit as lines, read as a co-op’s runs: the median is the typical streak, the mean is lifted by the long ones, and the gap between them is how much of the session was one good patch. On **TARGET**, the curve’s direction is the finding: climbing, a serve settling into the zone as the basket goes on; falling, fatigue, or a target the server does not have yet. The streak reads under the block cut alone; a 1st · 2nd, side or type cut skips serves, so the row reads a dash.' },
      { title: 'Read PLACEMENT and the Timeline', body: '**Placement** is the serve court per side with every landing: on target filled yellow, in but off target filled grey, a fault a hollow red ring. The three zone counts under it, the target zone’s count lit — and because the zones are the server’s own widths, a serve the server calls wide and the map calls middle is a conversation about the zone widths, not the serve. **Timeline** lists every serve — **Block 2 · serve 14 · wide · in · kick** — in order.' },
    ],
    notes: ['Compare like with like: a block of ten pairs and a block of ten first serves do not share a denominator; the cells say which unit a block counts.', 'A session with one block shows its cell faint; a session ended early shows every block of its setting with the unplayed ones faint — on the card, the cover and the cut track; a session with one side served has no Deuce · Ad track; an untyped session has no type track and no type table — absent, never greyed.', 'Sessions are not charted on the Stats tab; TREND is a serve session’s trend, and the longest streak and On target % are the two numbers to compare across sessions.', 'Serve sessions carry no patterns; a serve-started pattern is drilled in a VS rally with a serve start.', 'A linked coach receives a serve session live, with a notification at its start and end.'],
  },

  {
    slug: 'reports-and-replay', title: 'Read the match. Revisit the rally.', description: 'What each report page answers, how to read its rows against each other, and how to replay the points that decided it.', category: 'Analysis', duration: '12 min', screen: 'replay', screenAlt: 'Rallymetrica recorded rally replay with court and playback controls',
    intro: 'The final score tells you the result. The report tells you how it happened, one page per question — and the pages are in an order worth keeping: the shape of the match first, then the numbers that explain the shape, then the ball by ball record. A row on its own rarely means much; most of what follows is which rows to read against each other.',
    steps: [
      { title: 'Open the report', body: 'A finished match opens its report from its card on **Sessions → Matches** (or Home). A live match offers **Quick stats** from the court’s menu — the same report, so far — and its card offers **Replay so far**. Swipe between pages or use the page picker at the top. The pages a match has depend on what was recorded: a Score match has five, a Detailed match ten, and a rally or serve session opens the same report with its own pages.' },
      { title: 'Cover: the standard the numbers are judged against', body: 'The score and the winner first, then the **format block** — Best of 3 · sets to 6, the deuce rule, the tiebreak, the final set — from the match’s rules, never guessed from the score. While the match is live the cover ends with a **FORECAST** section: the chance to win from the current score — **LINDQVIST 56% TO WIN** — and a two-sided table of first serve in, serve points won, unforced errors, winners and double faults, each player’s number now against their own forecast, counts with the pace they are on (**13 · 30→37**). It is gone the moment the match closes. Read it before any number: 1st serve points won under no-ad is a different fact from the same figure with advantage games. Then **Tracking** (the level the match was recorded at — which tells you which pages to expect), **Duration**, ages and hands. On a rally session the block reads Mode · Format · Start · Length; on a serve session Format · blocks.' },
      { title: 'Momentum: where the match turned', body: 'The curve is the chance that the player named at the top goes on to win, after every point, read from the exact score and the rules — so a point at 30–0 in the first game barely moves it and a break point at 5–5 in a deciding set can move it a third of the way. Read three things. **The swings:** the starred one is the largest move the curve made; discs are strong swings, rings weak ones. Tap any swing for the comparison table: the stretch before against the stretch after — points played, win chance, winners, errors, first serves in. If the win chance moved while the share of points barely did, the big points were lost, not the rallies: go to Pressure. **The slope at the end:** a curve that was climbing when the match ended is a match that got away or one that was closed under pressure; either is a conversation. **The two currencies:** switch **Points → Aggression** under the legend to see form instead of win chance — who had been building more than giving away over the last dozen points. A lead on Points with a form line under even is a lead made of the opponent’s gifts.' },
      { title: 'Aggression: who was dictating', screen: 'aggression', alt: 'Rallymetrica Aggression report', body: 'The line is one player’s running **margin** or **efficiency** through the match, game by game: aggressive above EVEN, yielding below. Beneath it two headline rows — **Margin**, built minus given, and **Intent margin**, which also takes off the points a player was **Punished** for — then four sections you open with a tap: **Aggressive** (aces, winners, forced errors drawn), **Yielding** (unforced errors, double faults), **Punished** (points lost after his own short ball — a ball that fell in the opponent’s Finish zone inside his channel, not a volley, the opponent not pinned deep; only a Detailed match can count it) and **Opponent credit** (forced errors the opponent simply earned). The bars stack the punished points in red under the given side, so the bar’s full length is the intent margin. A player who never misses but feeds the forehand all afternoon finally reads as what he is: a small margin and a smaller intent margin. On **Efficiency** each player’s line carries a filled gap beneath it in his own colour — the cost of his gifts. Under ten decided points the rows read a dash.' },
      { title: 'Points: the summary, read as three pairs', body: '**Games won** heads the table: the score with no cut, and under the cuts the games those points fall in — holds under Serving, breaks under Returning, deuce games under Deuce, games held from break point down under Break point with Serving. The table lights the better side of each row, with the fraction under each percentage. Read it in pairs. **Points won against break points won:** 52% of points with 20% of break points is not a tennis problem but a pressure problem — Pressure will confirm it. **Winners against unforced errors:** more winners than unforced is a match played on your terms; the reverse means the opponent only had to keep the ball in. **Forced errors against unforced:** forced errors you committed are the opponent’s good play, unforced are yours to fix — a player with twice as many forced as unforced was beaten, one with the reverse beat themselves. The counts under the percentages matter: 67% of three points is noise.' },
      { title: 'Serve and Return: the same points from both sides', body: 'Both pages open with **Games won** — service games held on Serve, return games won on Return. **Serve** reads top to bottom as a chain. **1st serve in** high with **1st serve points won** low is a serve that goes in but goes nowhere — look at **Serves T · middle · wide** (Detailed) for a serve that always goes to the same place. 1st serve in low with 1st serve points won high is a big serve that misses too often: a percentage problem, not a weapon problem. **2nd serve points won** under 40% with **double faults** present is the second serve, and it is the row most matches are decided on. **Aces** and **service winners** are the free points; if both are near zero against a weak returner the serve is a start-the-point shot, not a weapon. **Return** is the receiver’s side of the same chain: **return in** low on first serves is position and reaction, on second serves it is intent — a second-serve return that keeps missing was being attacked too hard. **Return points won** against second serves is the single best measure of whether you punished the opponent’s weakness. Both pages carry the **Deuce · Ad** and **T · Mid · Wide** tracks on Detailed matches: read 2nd serve points won from the ad court alone before deciding the second serve is fine.' },
      { title: 'Pressure: the moments, all read from the score', body: 'Twelve rows and only the score behind them, so every match has this page. Read the gaps between a pressure row and the overall row. **Pressure points won** against **Points won**: ten points lower is a player who tightens; ten higher is one who waits for the big points and coasts the rest. **Break points won** (as receiver) against **Break points saved** (as server): a player who converts few and saves many is a server who plays the big point well and a returner who does not. **First points won** says how games start; **30–30** and **40–40** how they are decided. **Breaks consolidated** is the row coaches watch most: a break that is not followed by a hold was a break the opponent gave back for free, and a low number here with a healthy break-point row means the match was lost in the game after the good news. **Breaks back** is the mirror. **Set points won · saved** and **match points saved** are the closing rows; a low set-point conversion with a high set-point save says the sets were long and tight, not that the player cannot close. Pressure is a match page: a rally session has a tally, so it has no situation rows and no Pressure.' },
      { title: 'Placement: zones as rows, one measure at a time', screen: 'placement-depth', alt: 'Rallymetrica Placement Depth table showing zones and the selected measure', body: 'Detailed matches only. Placement answers *where did the balls go, and what came of it*. Five tabs on the header line — **Depth** (Deep · Mid · Finish), **Width** (Channel · Crosscourt · Down the line · Angles), **FH zone** (From my FH zone · Into their FH zone · Serve +1 · Return +1), **Lanes** (under Lanes in Settings) and **Serve** (T · Middle · Wide). The rows are that tab’s zones; the gavel track picks one measure for all of them. Nothing lit is **Balls**, the share of a player’s balls into the zone. **Punished:** you gave your opponent an attackable ball there — how often did you then lose the point? **Rewarded:** you deliberately played there — how often did you then win? **Converted:** you hit from inside your own zone — how often did you then win? (Depth only.) A note at the foot says in a sentence what the table is showing. A **deep** share under 40% is the depth problem Aggression names as Punished; **From my FH zone** under 60% is a player who runs around nothing; **Into their FH zone** high is feeding the opponent’s strength.' },
      { title: 'Placement on the court', screen: 'placement-court-depth', alt: 'Rallymetrica Placement court view with the Deep zone highlighted', body: 'The switch in the footer flips **Table** to **Court**: every landing as a dot, with two chip rows under the court. The ball rows mark balls the zones define — **Crosscourt ●**, **Down the line ◆**, **Angles ▲**, **From my FH zone ▼**, **Serve +1 ＋**, **Return +1 ✕** — and a ball that is two things wears both. The zone rows light a band in the zone’s own colour and keep only the dots inside it: Deep raises the blue bands at both baselines; on Lanes the dotted quarter lines divide each half and a lit lane turns green. One player lit shows his dots alone and his column; both lit shows each player’s zones on the half his balls land on. Put the **Set** cut on: the same court for set 1 and set 3 shows a player who stopped going for the line when the set got close.' },
      { title: 'Patterns: the plan, measured', body: 'When a Detailed match carried assigned patterns, the page lists each with **attempts · completions · won**. Read it as *openings · executions · results*, in that order: seven openings and three executions is a pattern the player recognised but could not finish — a drilling problem; seven openings and six executions with 30% won is a pattern the opponent has an answer to — a tactical problem; two openings in a whole match is a pattern the player never looked for. The coaching guide has the full reading.' },
      { title: 'Timeline: the ball by ball record', body: 'Every game as a row — the score as it stood, the server, the points inside with their endings and any star or note you added on court. Open a game to inspect its points; tap a point to correct it if it was recorded wrongly, and the whole report recalculates. The **replay icons** on a point, a game or a set open the replay there. The Timeline is also where a swing you found on Momentum becomes real: the swing’s point range is listed here, so you can see the four points that turned the second set rather than the curve that summarised them.' },
      { title: 'Cuts: ask the narrower question', body: 'Every table page, Momentum and Placement’s court share the filter track: **Set**, **Situation**, **Score**, and the page’s own tracks (serving · returning, rally length, starred points, serve side and zone). A cut keeps only the points that fit and recomputes every row. The questions worth asking first: the Serve page under **Break point** (how do I serve when it matters), the Points page under **9+** (do I win the long rallies), the Return page under **Set 3** (did the return hold up). An option greys out when no row on the page can use it — grey means the question is empty, not a fault. The cuts guide covers all of them.' },
      { title: 'Replay: see the point again', body: 'Replay animates the recorded placements onto the court — it is not video. On a Detailed match it draws the full rally path, ball by ball; on Counter and Score it steps through the points by their endings. Play and pause, step with **previous · next**, and choose the unit — **Shot · Point · Game · Set** — when the selection holds enough of them. Tap the momentum strip under the court to jump to a moment: the starred swing is the natural place to start. A live match card’s **Replay** opens the match to date; a linked coach can watch it on their own phone as the points arrive. From five tracked matches a side the card’s footer carries a **FORECAST** chip — the leader and the chance, moving with every point — and tapping it flips the card to the forecast’s back: the headline, both players’ serve points won and unforced errors so far, and **Back to score**.' },
      { title: 'Share: the report on paper, the data in a spreadsheet', body: '**Share** on any report opens one sheet: send the report as a **PDF** — page for page, the cover through the timeline, with one Placement sheet per tab and the landings after them — save it to Files or print it; or **Export CSV**, one row per ball with every recorded fact beside it, for a spreadsheet or a pivot table. The whole season exports from **Settings → Data → Export stats to CSV**: a row per match and player, every statistic with its fraction.' },
    ],
    notes: ['The pages a match has: Score — Cover · Momentum · Points · Pressure · Timeline; Counter adds Aggression · Serve · Return; Detailed adds Placement · Landings · Patterns. Shots appears only on a match with recorded speeds.', 'Every number is computed from the points you tapped under the match’s rules. A dash means the value was not captured at this level or no points fall under the cut — never a zero.', 'A report page lights the better side of a row; rows without a direction (the direction shares) light nothing.', 'The same report opens on a practice session with that kind’s pages — see the Rally, Co-op and Serve session guides.', 'Point, Game and Set replay controls appear when the selected replay contains enough of those units.'],
  },
  {
    slug: 'stats-and-trends', title: 'See your progress over time', description: 'Am I improving? Was that a normal day? How do I compare — with a rival, or two students against the same opponent?', category: 'Analysis', duration: '6 min', screen: 'stats', screenAlt: 'The Stats tab: one metric across ten matches with its trend and usual range',
    intro: 'One match is one data point. The Stats tab charts one metric across a window of matches and answers five questions in order: where is my normal, was this match typical, am I improving, what should the next one be, and how do I compare. Each answer is a tap or two.',
    steps: [
      { title: 'Find your normal', body: 'Open **Stats**, choose a category and metric — say **Serve → 1st serve in** — set the window to **10** and the view to **MA**. The flat line is your average over those matches. The shaded band is your **usual range**: the middle 80% of where a normal match for you lands. It appears once five matches carry the metric.' },
      { title: 'Ask whether today was typical', body: 'Look at the last dot. Inside the band it was a normal day, even if its dot sits coral below the average — change nothing. Outside the band it is notable, high or low: tap the dot to open that match, then look for the reason in the report (the opponent, the surface, one set, one situation).' },
      { title: 'Ask whether you are improving', body: 'Switch to **Trend**. The legend states the slope — **+0.4% per match** — and the dots are yellow where a match beat the trend, coral where it fell short (the line itself stays one quiet line; the trend is the dashed one). Three matches in a row on the same side of the average say the level has moved; the slope says how fast. A flat trend with a wide band means the problem is consistency, not level. Use **7** or **10**: three matches cannot show a trend.' },
      { title: 'Ask what the next one should be', body: 'Switch to **Forecast**. The dashed line is the forecast as it stood before each match — made from the matches before it alone, never with hindsight, so the first five carry none — and the star one slot past the last match is the next one, with its 80% range as a bar. Each dot reads against its own forecast: tap one for **+4 vs forecast · forecast was 58%**. The legend says which model fitted — **Forecast · level**, **trend** or **trend, damping** — and the range never shrinks to nothing, however steady the last five were. The window only decides how much of the curve you see: **Last 3** shows three dots and the same star **All** shows. **Win rate** is different in kind — its baselines are what the match model said before each match, opponent and format included, and its star is your chance to win your next match against the players you actually face (see the Forecast section of the stats reference).' },
      { title: 'Ask whether it improved where it matters', body: 'Put a cut on before you judge. **Situation → Break point**, or **Score → 30–30**, recomputes every match from those points only: **2nd serve points won under break point** across ten matches is the honest test of the second serve you have been practising. A dotted gap is a match with no such points, not a zero.' },
      { title: 'Compare with one opponent', body: 'Change **Any opponent** to a name. The window narrows to that head-to-head, and the same metric reads against that player only. Compare the average here with the average against anyone: if your first serve drops ten points against one rival, that is a tactical fact, not a bad day.' },
      { title: 'Coach: compare two students against the same opponent', body: 'On the **Coach** plan pick a player, a second player, and a common opponent. Both appear as series on one axis — same metric, same cut, same opponent. Read two things: who sits higher, and whose dots scatter less. The steadier player is often the one to trust on the big day; the higher, less steady one has the bigger upside and the clearer thing to work on.' },
      { title: 'Start from a profile', body: 'In **Players → a player → Trends** the same window applies. Tap any metric row to open its chart in Stats with the player already chosen.' },
    ],
    notes: ['The moving average needs two matches, the trend three, the usual range five.', 'The usual range is a prediction band: it says where your next normal match should land, which is why one match outside it is worth a look and one inside it is not.', 'A match in progress is drawn as the last, hollow point and left out of the average, the trend and the band until it finishes.', 'A missing value means “not captured at that tracking level” or “no points under this cut”. It is never a zero.', 'Stats charts matches only. A practice session’s trend is in its own report — Trend on a serve session, Runs on a co-op.', 'The reference page explains the band and the colours in full: Learn → The stats engine → Stats over time.'],
  },
  {
    slug: 'practice-plan', title: 'Turn a report into a practice plan', description: 'Read Momentum, Aggression and Pressure in the right order, pick one thing to fix, and check next week whether it moved.', category: 'Analysis', duration: '7 min', screen: 'momentum', screenAlt: 'The Momentum page with the largest swing starred',
    intro: 'A report earns its place only if it changes next week’s practice. This is the order to read it in, the one question each page answers, and the way to leave with a single number to improve.',
    steps: [
      { title: 'Start with Momentum, not the score', body: 'Open the report and go to **Momentum → Points**. Find the starred swing — the largest move the curve made — and tap it. The popover compares the stretch before with the stretch after: points played and win chance for each player. If the win chance fell while the share of points barely moved, the big points were lost, not the rallies: go to **Pressure**. If both fell together, a stretch of poor play: put the **set** cut on that set and go to **Aggression**.' },
      { title: 'Ask Aggression who was dictating', body: 'The **Margin** or **Efficiency** line sits above EVEN when a player is building more points than they give away. **Intent margin** is the stricter read: it also charges the points they were **Punished** for. If **Yielding** is the bigger section, the problem is errors — margins and shot selection. If **Punished** is large, the problem is depth: short, central balls that invited the attack, and Placement’s **Finish: Punished** row says how often they cost the point. If both are small, the player made nothing happen and the opponent decided the match (a passivity problem). Switch Momentum to **Aggression** to see when in the match the dictating stopped.' },
      { title: 'Check Pressure for the moments', body: 'Points won overall at 52% with break points won at 20% is not a tennis problem; it is a pressure problem. Read **30–30**, **40–40**, **break points saved**, **first points won**. A gap of ten points or more between the pressure rows and the overall row points at the practice format, not the stroke: play practice games from 30–30, serve second serves only, start sets at 4–4.' },
      { title: 'Find the shot', body: '**Serve**: 2nd serve points won low with double faults present is the second serve; 1st serve in high with 1st serve points won low means the serve goes in but goes nowhere — check **T · Mid · Wide**. **Return**: return in % low on first serves is position, not technique. **Placement**: a low deep % is depth; a direction share that is nearly all crosscourt is a pattern the opponent has read; a high **Finish: Punished** is the short ball that cost the points.' },
      { title: 'Pick one thing and write it as a number', body: 'One metric, one cut, one window: “2nd serve points won under break point — 31% now, 45% over the next five matches.” Not three things. The report will still be there next week.' },
      { title: 'Check it on Stats', body: 'Open **Stats**, choose that metric, put the same cut on, set the window to **7** and the view to **Trend**. It has moved when the slope is positive and the last three dots sit above the old average. One good match inside the old usual range is not evidence yet; it is a normal day.' },
      { title: 'Practise it as a session', body: 'The drill the report asks for is a session away. Second serve under pressure: a **VS rally** with a serve start and **Serves · 1** — a fault loses the point. Serve placement: a **serve session** with the target on the weak side, read **On target %** block by block. Depth: a **co-op** counting runs, then the **Endings** page says whether the misses were long or into the net.' },
      { title: 'Coaches: hand it back as a pattern', body: 'If the fix is a sequence — serve wide, forehand into the open court — draw it in **Patterns**, assign it, and have the player include it in their next Detailed match or rally session. The report’s **Patterns** page then returns attempts, completions and points won, which is the fix measured.' },
    ],
    notes: ['Momentum → Points needs only the score. Aggression needs a Counter match; Punished needs the landings of a Detailed one.', 'The aggression rows read a dash under ten decided points — a short match says nothing about aggression.', 'Five matches is the smallest honest window for a change; do not chase one result.', 'The reference page defines every row named here: Learn → The stats engine.'],
  },
  {
    slug: 'cuts', title: 'Ask a narrower question', description: 'Set, situation, score, serve side, rally length: the same number under the right cut answers a sharper question.', category: 'Analysis', duration: '5 min', screen: 'report-points', screenAlt: 'A report page with the filter track: sets, situation and score',
    intro: 'Every table page, Momentum and Landings share one filter track, and so does the Stats tab. A cut keeps only the points that fit and recomputes every row from them. Learning the five cuts turns a page of averages into answers.',
    steps: [
      { title: 'Set', body: '**S1 … S5** keeps one set. “Did the first set lie?” — compare 1st serve in under S1 with S3. On Momentum a set cut fades the other sets rather than hiding them, so the swing can still be read against the whole match. On a rally session the cells are blocks — **B1 … B5**.' },
      { title: 'Situation', body: 'One at a time: **Break point** (the receiver is a point from breaking), **Break game** (every point of a game the receiver won), **Break consolidation** (the service game straight after a break), **Tiebreak**, **Set point**, **Match point**. “How do I serve on break point?” — Serve page, Break point, read 1st serve in and 2nd serve points won against the uncut page.' },
      { title: 'Score', body: 'The game score before the point, server first: the presets **First point · 30–30 · Deuce · Advantage**, or any pair on the two wheels. A score cut stays live inside a game situation — “30–30 points inside break games” is a legal question. Pressure turns the score cut off because each of its rows already names a score.' },
      { title: 'The page’s own tracks', body: '**Serving · Returning**; rally length **0–4 · 5–8 · 9+**; **starred** points; on the serve and return pages **Deuce · Ad** and **T · Mid · Wide**; on the landing maps **Serve · Return · Rally · End** — one class of ball at a time. Rally length is a property of the whole point, so on the Serve page **9+** reads “where my serves landed in the points that became long rallies” — a question about which serve starts the rallies you lose.' },
      { title: 'Read the grey', body: 'An option greys out when no row on the page can use it, or when it could not change the row: rally length on aces, break point on break points. Grey is the page telling you the question is empty, not a fault. A dimension the record cannot hold is absent altogether: a rally session has no Situation or Score, a feed-started one no Serving · Returning.' },
      { title: 'Carry the cut to Stats', body: 'The Stats tab has the same track. A question that was true for one match — “I lose the long rallies on my second serve” — becomes a trend across ten: 2nd serve points won, 9+, window 10.' },
    ],
    notes: ['Cover and Patterns take no cuts; Win rate takes none.', 'A missing value under a cut means no points fit. In a trend it is a gap, not a drop.', 'Starred points are the ones you starred on the live court when saving the point — your own highlight reel as a cut.', 'A serve session has its own track — block, 1st · 2nd, Deuce · Ad, the type — and none of the match cuts.', 'The full matrix of which cut applies to which row is in the reference: Learn → The stats engine → Cuts.'],
  },
  {
    slug: 'coach-player-link', title: 'Link your coach. Share the match live.', description: 'Connect both phones with encrypted sharing, then unlink whenever you choose.', category: 'Coaching', duration: '5 min', screen: 'coach-link', screenAlt: 'Rallymetrica Coach link screen showing the pairing code',
    intro: 'A linked coach can follow a player’s match on their own phone. Each saved point updates the shared match as it lands, giving both people the same score, report, and recorded rallies to review. Your matches live on your phone, and everything sent between the two phones is end-to-end encrypted.',
    steps: [
      { title: 'Show the player’s code', body: 'On the player’s phone, open the gear on **Home**, then **Settings → Coach link**. Display the QR code. This screen requires the **Player** plan.' },
      { title: 'Scan on the coach’s phone', body: 'On the **Coach** plan, open **Settings → Students → Add student**. Allow camera access and scan the code displayed on the player’s phone.' },
      { title: 'Approve the link', body: 'The player sees the coach’s name and **Wants to link**. Tap **Link** to approve. The coach then sees the player’s linked confirmation. The initial sync shares the profile, past matches, and any live match recorded so far.' },
      { title: 'Follow saved points', body: 'Record the match on the player’s phone. On the coach’s phone, find the shared live match on **Home** or under **Sessions**, then tap **Report**. Updates arrive after each saved point, including corrections made with Undo.' },
      { title: 'Review together', body: 'Use **Replay** to revisit the recorded match. In **Settings → Students**, open the student to use **Open profile**. Coach-created pattern assignments sync back to the player for their next match setup.' },
      { title: 'Unlink when you choose', body: 'On the player’s phone, open **Settings → Coach link**, tap **Unlink**, and confirm **Unlink**. New sharing stops on your phone. Once the coach’s app is online and receives the unlink, match copies received through the link are removed. Your original recordings remain on your phone.' },
    ],
    notes: ['Points arrive on the coach’s phone in the background, with a notification every set, game or point as the coach chooses under Settings → Notifications — per student under Settings → Students. Unfinished shot taps are not shared until the point is saved.', 'Rally and serve sessions arrive the same way; for a session the coach is told at its start and end.', 'Offline updates queue and sync in order when connectivity returns. Offline unlinking also waits for connectivity to notify the other phone.', 'Shared matches are read-only on the coach’s phone; the recording phone controls the match.', 'The delivery relay stores encrypted messages until retrieval, plus device and connection details. It cannot read the shared match content.', 'Unlinking does not remove independently recorded coach matches or copies already exported or shared outside the link. Pausing stops new updates and keeps received copies.', 'Detailed tracking supplies the placements needed for full rally replay and pattern execution results.'],
  },
  {
    slug: 'coaching-patterns', title: 'Assign a pattern. Measure its success.', description: 'Draw a pattern of play, assign it, and read attempts · completions · won as a diagnosis, not a score.', category: 'Coaching', duration: '9 min', screen: 'pattern-editor', screenAlt: 'Rallymetrica coach pattern editor with a drawn shot sequence and Assign to',
    intro: 'A pattern of play is a tactical idea written as a sequence of landing zones: serve wide, forehand into the open court. Rallymetrica lets a coach draw it, hand it to a player, and have every Detailed match or rally session report how often the player found the opening, how often they finished the sequence, and how often that won the point. Three numbers, and each one points at a different kind of work.',
    steps: [
      { title: 'Open the pattern library', body: 'On the **Coach** plan, the **Patterns** tab holds your library — every pattern with the players it is assigned to. Tap **+ New pattern** and start from a **Blank court** or from a template (serve wide → forehand open court, serve T → backhand cross, the approach down the line). A template is a starting drawing, not a rule; move anything.' },
      { title: 'Draw the sequence', body: 'Name the pattern for what it is meant to do (“Wide serve, open court”), then place the balls: drag the ball handle for where the shot is struck and the landing handle for where it lands; **+ Shot** adds the next ball, **Remove last** takes it back. Two to four landings make a pattern. Consecutive landings must alternate sides — a pattern describes an exchange, not one player’s two shots in a row. When the first ball lands in a service box the pattern opens with a serve, and the **Serve** option appears: **Any · 1st · 2nd** says which serve the pattern applies to, **None** means the opening ball is a rally ball.' },
      { title: 'Draw it the way the engine will read it', body: 'The engine matches landing **zones**, not exact spots, and the zones are the player’s own — the channel, the deep zone and the forehand zone as set under their profile’s **Zones**. So draw the landing where the zone is, not where the perfect ball would be: a “deep crosscourt” that you draw an inch inside the baseline is in the deep zone whether the real ball lands there or a metre shorter, as long as it clears the player’s deep line. A pattern drawn with four exact landings will almost never complete; three honest zones will.' },
      { title: 'Assign and save', body: '**Assign to** lists your roster; pick the players the pattern is for and **Save pattern**. The drawing and the assignments save together. A linked player receives the pattern at the next sync and sees it in their own match setup; a player on your phone has it at once. Reassigning later does not change any match already recorded — a match keeps the patterns selected at its start.' },
      { title: 'Put it in the match', body: 'In **New match**, choose **Detailed** (patterns can only be matched against landings), then under **Pattern focus** turn on **Include patterns** and pick up to three per player; a coach can also pull one in with **+ From library**. During the match nothing changes on the court — the engine reads the landings you tap. A **rally session** (VS or co-op) takes a focus pattern the same way.' },
      { title: 'Read attempts, completions, won', body: 'The report’s **Patterns** page lists each pattern as **n of m attempts · x% won**. An **attempt** is counted when a point reaches the pattern’s opening zone with the right player hitting and the right serve context — the opening presented itself. A **completion** means the full sequence of zones was recorded in order — the player executed it. **Won** is the share of completed-pattern points that the player won. Each pattern counts at most once per point, and the three numbers are a chain: openings, then executions, then results.' },
      { title: 'Diagnose from the three numbers', body: 'Read the chain from the left. **Few attempts** (two openings in a three-set match) means the player is not creating or not recognising the opening — a serve pattern with few attempts on a 1st-serve pattern is a first serve not going where it must; on a rally pattern it is a player who does not look for the ball. **Many attempts, few completions** (3 of 9) is a drilling problem: the player finds the opening and cannot finish the sequence — the second or third ball is the one to practise, and the Landings page under **Rally** shows where it actually went. **Many completions, low won** (7 of 8 · 29%) is a tactical problem: the pattern works as a sequence and the opponent has an answer — change the pattern, not the player. **Many completions, high won** is the plan working; the question becomes why only eight attempts in a match of ninety points.' },
      { title: 'Compare across matches', body: 'The player’s profile brings patterns together across their Detailed matches, so a pattern reads 23 of 41 · 61% over the season rather than 3 of 7 tonight. Read the trend in the chain: completions rising across matches is the drilling paying off; won falling as completions rise is opponents adapting. On a co-op session the page reads completions of attempts with no won — there are no points to win — which makes a co-op the cleanest place to drill the sequence itself.' },
    ],
    notes: ['The library and editor require Coach; a linked Player includes patterns their coach assigned. Serve sessions carry no patterns.', 'Pattern counts come only from recorded landings: Counter and Score matches have no attempts and no completions.', 'Switching away from Detailed mid-match stops pattern matching from that point; the points already matched keep their counts.', 'A pattern that never completes is usually drawn too precisely. Loosen the landings to the zone and compare the next match.', 'The won percentage is of completed-pattern points, so it answers “does the plan work when executed”, never “is the player winning”.', 'Cancel discards unsaved edits; Save pattern writes the drawing and the assignments together.'],
  },
  {
    slug: 'run-your-roster', title: 'Run your roster', description: 'Link students, choose how you are told, follow matches live, compare players, and hand the work back as patterns.', category: 'Coaching', duration: '6 min', screen: 'students', screenAlt: 'Settings → Students: linked students with their live-score settings',
    intro: 'Coach puts every player you work with in one place: their matches and sessions arrive live, their profiles and trends are yours to read, and the Stats tab compares them. This is the weekly routine.',
    steps: [
      { title: 'Link each student', body: '**Settings → Students → Add student**, scan the code on the student’s phone, and they approve on theirs. The first sync brings their profile and past matches. **Coach** links up to five students; **Academy** up to twenty-five. Over the cap, **Settings → Plan** upgrades you; nothing is unlinked by a plan change.' },
      { title: 'Decide how you want to be told', body: '**Settings → Notifications → Live scores** sets the default: **Off · Every set · Every game · Every point**. Then, under **Settings → Students**, each student carries their own strip — **Off · Set · Game · Point** — which overrides the default for that student. Every point for the match you cannot be at; every set for the rest. A practice session tells you when it starts and ends.' },
      { title: 'Follow a match live', body: 'A student’s live match or session appears on **Home** and under **Sessions**. Open it for the report so far and **Replay**. Points arrive after each saved point, corrections included. The match is read-only on your phone; the student’s phone records it.' },
      { title: 'Read the student, not the match', body: '**Players → the student** opens their profile: **Trends** across the shared window, **Patterns** with completions across their Detailed matches, **Zones** with their zone traits — where the channel, the deep zone and the forehand zone begin for this player, in %, feet or metres, the forehand in O’Shannessy’s lanes if you prefer. Set the zones to the player, because every placement row reads through them.' },
      { title: 'Compare two students', body: '**Stats**: pick a player, a second player, and a common opponent. Two series on one axis, same metric, same cut. Who sits higher and whose dots scatter less are different facts; the steadier player is the one to trust on the day, the higher, less steady one has the clearer thing to work on. The same chart is how you tell a student the truth with numbers rather than opinion.' },
      { title: 'Hand the work back as a pattern', body: 'Draw the sequence in **Patterns**, **Assign to** the student, save. It syncs to their phone; they include it in their next Detailed match or rally session; **attempts · completions · won** come back in that record’s report and accumulate on their profile.' },
      { title: 'Pausing and unlinking', body: 'The student controls the link: **Settings → Coach link → Unlink** on their phone. Once your app is online and receives it, the copies you received through the link are removed; your own recorded matches stay. Pausing stops new updates and keeps the copies.' },
    ],
    notes: ['You appear on Players under YOU with your own matches; students sit under ROSTER, each card’s bookmark carrying the player’s initials, the live ones pulsing. A coach is never a student on their own phone.', 'Shared matches are read-only; corrections come from the recording phone.', 'Coach and Academy differ only in the student cap: five or twenty-five.', 'Points arrive in the background with the notification you chose; unfinished shot taps are not shared until the point is saved.'],
  },
]
